export const GUIDE_BY_ID = Object.fromEntries(GUIDE.map((g) => [g.id, g])) as Record<GuideId, GuideEntry>;

export function localized(entry: GuideEntry, language: Language): Localized {
  return entry[language] ?? entry.en;
}
